import React, { useState } from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";
import Zoom from 'react-medium-image-zoom'
import 'react-medium-image-zoom/dist/styles.css'

const Container = styled.div`
  padding: 20px;
  text-align: center;
`;

const Title = styled.h2`
  font-size: 24px;
  margin-bottom: 20px;
`;

const ImageWrapper = styled.div`
  display: flex;
  justify-content: center;
  align-items: center;
`;

const Image = styled.img`
  max-width: 100%;
  height: auto;
  border-radius: 10px;
  border: 1px solid #ccc;
  cursor: ${(props) => (props.scale > 1 ? "zoom-out" : "zoom-in")};
`;

const DatasetStatistic = () => {
  const { t } = useTranslation();
  const [scale, setScale] = useState(1);

  return (
    <Container>
      <Title>{t("datasetStatistic.title")}</Title>
      <TransformWrapper
        initialScale={1}
        minScale={0.5}
        maxScale={3}
        centerZoomedOut={false}
        wheel={{ step: 0.1 }}
        doubleClick={{ disabled: true }}
        panning={{ velocityDisabled: true }}
        onZoomStop={({ state }) => setScale(state.scale)}
      >
        <TransformComponent>
          <ImageWrapper>
            <Image src="/Statistic1.jpg" alt="Statistic" scale={scale} />
          </ImageWrapper>
        </TransformComponent>
      </TransformWrapper>
    </Container>
  );
};

export default DatasetStatistic;
